      let agentIndex = this.agents.indexOf(this.selectedAgent);
      this.index =
        "SUP-" +
        (agentIndex < 10
          ? "000" + agentIndex
          : agentIndex < 100
          ? "00" + agentIndex
          : agentIndex < 1000
          ? "0" + agentIndex
          : agentIndex);
      console.log(this.customer);
      this.selectedId = this.selectedAgent.id;
